
.card {
  width: 100%;
  max-width: 680px;
  background-color: var(--c-surface-warm);
  border: 2px solid var(--c-border);
  border-radius: 14px;
  box-shadow: 0 4px 16px rgba(90, 74, 66, 0.10);
  display: flex;
  flex-direction: column;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
  overflow: hidden;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(135deg, var(--c-primary), var(--c-accent));
}

.title {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
}

.phase-tag {
  font-size: 11px;
  color: #fff;
  background: rgba(255, 255, 255, 0.25);
  padding: 2px 10px;
  border-radius: 10px;
}

.progress-list {
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.status-line {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px dashed var(--c-border);
  background: #fff;
}

.status-label {
  font-size: 11px;
  color: var(--c-primary-deep);
  font-weight: 700;
  flex-shrink: 0;
}

.status-text {
  color: var(--c-text);
  font-size: 12px;
}
